/**
 * Fingerprints from artifacts/demo/*.groth16.json.
 * Full proof bytes stay in those files for the Desk; the room only shows seals.
 */
export type Groth16Receipt = {
  allowed: boolean;
  programVKey: string;
  publicValues: string;
  proof: string;
};

export const PROGRAM_VKEY = "0x00035e8be65b2881b5409b3238047ddd679c9cce04cb4140973e04e9ed3330cd";

/** Guest token id (not the deployed TBill address). */
export const RECEIPT_TOKEN = "0x3333333333333333333333333333333333333333";
export const SENDER_ORG = "0x1111111111111111111111111111111111111111";
export const RECEIVER_ORG = "0x2222222222222222222222222222222222222222";

export const POLICY_HASH_V1 = "0x3e9abaca0aad9ede81f4474766c846d8539f70688e1c8f521bbe1597874e3dc4";
export const POLICY_HASH_V2 = "0x2a32391a76c35a36352b711f9152c0d0a340cd686850c8ef25fbb11c71b89e7b";
export const TRANSFER_ATTEMPT_1 = `0x${"44".repeat(32)}`;
export const TRANSFER_ATTEMPT_2 = `0x${"45".repeat(32)}`;

export const CHANI_OUTBOUND: Groth16Receipt = {
  allowed: true,
  programVKey: PROGRAM_VKEY,
  publicValues:
    "",
  proof: "0x4388a21c…94178",
};

export const PAUL_INBOUND_V1: Groth16Receipt = {
  allowed: false,
  programVKey: PROGRAM_VKEY,
  publicValues:
    "",
  proof: "0x4388a21c…d6fee",
};

export const CHANI_OUTBOUND_RETRY: Groth16Receipt = {
  allowed: true,
  programVKey: PROGRAM_VKEY,
  publicValues:
    "",
  proof: "0x4388a21c…bcf702",
};

export const PAUL_INBOUND_V2: Groth16Receipt = {
  allowed: true,
  programVKey: PROGRAM_VKEY,
  publicValues:
    "",
  proof: "0x4388a21c…3d11a5",
};

export function shorten(hex: string): string {
  if (hex.includes("…")) {
    return hex;
  }
  const body = hex.startsWith("0x") ? hex.slice(2) : hex;
  if (body.length <= 8) {
    return hex.startsWith("0x") ? hex : `0x${hex}`;
  }
  return `0x${body.slice(0, 4)}…${body.slice(-4)}`;
}

export function receiptsFor(phase: "idle" | "pending" | "published" | "settled"): {
  outbound: Groth16Receipt;
  inbound: Groth16Receipt;
} {
  if (phase === "settled") {
    return { outbound: CHANI_OUTBOUND_RETRY, inbound: PAUL_INBOUND_V2 };
  }
  return { outbound: CHANI_OUTBOUND, inbound: PAUL_INBOUND_V1 };
}
